import type { TableName, Data } from '../db'

interface IGlideRecord<T extends TableName = TableName> {
    table: T
    addQuery<F extends keyof Data<T>>(element: F, value: Data<T>[F]): void
    query(): void
    get(id: string): void
    get<F extends keyof Data<T>>(element: F, value: Data<T>[F]): void
    getValue<F extends keyof Data<T>>(element: F): Data<T>[F]
    isValid(): boolean
    isValidRecord(): boolean
    initialize(): void
}

export type GlideRecord<T extends TableName = TableName> = IGlideRecord<T> & Data<T>

export interface _GlideRecordConstructor {
    new <T extends TableName = TableName>(n: string): GlideRecord<T> & Data<T>
}

export declare const GlideRecord: IGlideRecord & _GlideRecordConstructor

export declare function newGlideRecord<T extends TableName>(table: T): GlideRecord<T>
